import { unSelectMessage } from '../../../../store/actions/dialog-actions';
import { selectUser } from '../../../../store/actions/user-actions';
import { store } from '../../../../store/store';
import style from './style.module.css';
import React from 'react';

type UserContactProps = {
  login: string;
  active: boolean;
  messages: number;
};

export const UserContact: React.FC<UserContactProps> = ({
  login,
  active,
  messages = 0,
}) => {
  const clickHandler = () => {
    let userSelected = store
      .getState()
      .users.usersAnother.active.filter((user) => user.login === login);
    if (userSelected.length === 1) {
      store.dispatch(selectUser(userSelected[0]));
      store.dispatch(unSelectMessage());
    } else {
      userSelected = store
        .getState()
        .users.usersAnother.inactive.filter((user) => user.login === login);
      store.dispatch(selectUser(userSelected[0]));
      store.dispatch(unSelectMessage());
    }
  };

  return (
    <li className={style['user-contact-container']} onClick={clickHandler}>
      <div
        className={
          active
            ? `${style['user-status']} ${style['active']}`
            : style['user-status']
        }
      ></div>
      <label className={style['user-login']}>{login}</label>
      {messages !== 0 && (
        <label className={style['user-messages']}>{messages}</label>
      )}
    </li>
  );
};
