import { useSelector } from 'react-redux';
import { UserActions } from '../../../store/constants/action-constants';
import {
  AuthCallback,
  useAuthorization,
} from '../../custom-hook/use-authorization';
import Button from '../../shared/button/Button';
import style from './style.module.css';
import { RootState, store } from '../../../store/store';
import { useNavigate } from 'react-router-dom';
import { logout } from '../../../store/actions/user-actions';

export const Header: React.FC = () => {
  const headerText = 'Веселый чатик';
  const userText = 'Пользователь: ';
  const buttonText = 'Выход';
  const infoText = 'Инфо';

  const user = useSelector((store: RootState) => store.users.userCurrent);
  const navigate = useNavigate();

  const authCallback: AuthCallback = {
    pending: () => {},
    fullfilled: () => {
      store.dispatch(logout(user));
      navigate('/login');
    },
    rejected: () => {},
  };
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [messageResult, authSendHandler, reset] = useAuthorization(
    user,
    UserActions.LOGOUT,
    authCallback
  );

  return (
    <section className={style.header}>
      <article className={style['content-wrapper']}>
        <label>{`${userText}${user.login}`}</label>
        <label>{headerText}</label>
      </article>
      <Button
        text={infoText}
        callback={() => navigate('/about')}
        small={true}
      />
      <Button text={buttonText} callback={authSendHandler} small={true} />
    </section>
  );
};
