import { useSelector } from 'react-redux';
import { sendMessage } from '../../../../core/services/send-message';
import Button from '../../../shared/button/Button';
import style from './style.module.css';
import React, { useEffect, useState } from 'react';
import { RootState, store } from '../../../../store/store';
import { DialogActions } from '../../../../store/constants/action-constants';
import { setReaded } from '../../../../core/services/set-readed';
import { unSelectMessage } from '../../../../store/actions/dialog-actions';

export const DialogInput: React.FC = () => {
  const buttonText = 'Отправить';
  const placeholderText = 'Ваше сообщение...';

  const selectedUser = useSelector(
    (store: RootState) => store.users.userSelected.login
  );
  const selectedMessageId: string = useSelector(
    (store: RootState) => store.dialogs.messageSelected
  );

  useEffect(() => {
    const dialogs = store.getState().dialogs.messages;
    dialogs.forEach((dialog) => {
      const message = dialog.messages.filter(
        (message) => message.id === selectedMessageId
      );
      if (message.length === 1) {
        setMessage(message[0].text);
      }
    });
  }, [selectedMessageId]);
  const [message, setMessage] = useState('');

  const inputChangeHandler = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessage(event.currentTarget.value);
  };
  const inputKeyDownHandler = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.shiftKey === false && event.key === 'Enter' && event.code === 'Enter'){
      event.preventDefault();
      sendClickHandler();
    }
    if (event.shiftKey === true && event.key === 'Enter' && event.code === 'Enter'){
      event.preventDefault();
      setMessage(event.currentTarget.value + '\r\n');
    }
  };
  const sendClickHandler = () => {
    if (message !== '') {
      if (selectedMessageId === null) {
        const payload = {
          message: {
            to: selectedUser,
            text: message,
          },
        };
        sendMessage(DialogActions.MSG_SEND, payload);
      } else {
        const payload = {
          message: {
            id: selectedMessageId,
            text: message,
          },
        };
        sendMessage(DialogActions.MSG_EDIT, payload);
      }
      cancelEditHandler();
      setMessage('');
      setReaded();
    }
  };
  const submitHandler = (event: React.KeyboardEvent<HTMLFormElement>) => {
    event.preventDefault();
    sendClickHandler();
  };
  const cancelEditHandler = () => {
    store.dispatch(unSelectMessage());
    setMessage('');
  };
  return (
    <form className={style['dialog-input']} onSubmit={submitHandler}>
      <textarea
        value={message}
        className={style['dialog-input-field']}
        placeholder={placeholderText}
        onChange={inputChangeHandler}
        onKeyDown={inputKeyDownHandler}
        disabled={selectedUser === null}
      ></textarea>
      {selectedMessageId !== null && (
        <label
          className={style['dialog-input-cancel']}
          onClick={cancelEditHandler}
        >
          X
        </label>
      )}
      <Button
        text={buttonText}
        callback={sendClickHandler}
        small={true}
        disabled={selectedUser === null || message === ''}
      />
    </form>
  );
};
