import { useSelector } from 'react-redux';
import { Message } from '../../../../store/actions/dialog-actions';
import { RootState } from '../../../../store/store';
import style from './style.module.css';
import React from 'react';

type DialogMessageProps = {
  message: Message;
  innerRef?: React.RefObject<HTMLDivElement>;
  menuCallback?: (
    event: React.MouseEvent | React.TouchEvent,
    idMessage: string
  ) => void;
};

const getStatus = (isDelivered: boolean, isReaded: boolean): string => {
  const textSended = 'Отправлено';
  const textDelivered = 'Доставлено';
  const textReaded = 'Прочитано';

  if (isReaded) {
    return textReaded.toLowerCase();
  }
  if (isDelivered) {
    return textDelivered.toLowerCase();
  }

  return textSended.toLowerCase();
};

export const DialogMessage: React.FC<DialogMessageProps> = ({
  message,
  innerRef,
  menuCallback,
}) => {
  const currentUserText = 'вы';
  const textEdited = 'Изменено';

  const currentUser = useSelector(
    (state: RootState) => state.users.userCurrent.login
  );

  const clickMenuHandler = (event: React.MouseEvent | React.TouchEvent) => {
    if (typeof menuCallback === 'function' && currentUser === message.from) {
      menuCallback(event, message.id || '');
    } else {
      event.preventDefault();
    }
  };

  return (
    <div
      ref={innerRef}
      className={
        currentUser === message.from
          ? `${style['message-container']} ${style.current}`
          : `${style['message-container']} ${style.another}`
      }
      onContextMenu={clickMenuHandler}
      onTouchEnd={clickMenuHandler}
    >
      <div className={style.message}>
        <div className={style.header}>
          <label>
            {message.from === currentUser ? currentUserText : message.from}
          </label>
          <label>{new Date(message.datetime).toLocaleString()}</label>
        </div>
        <div className={style.text}>{message.text}</div>
        <div className={style.footer}>
          <label>{message.status.isEdited ? textEdited : ''}</label>
          <label>
            {currentUser === message.from &&
              getStatus(message.status.isDelivered, message.status.isReaded)}
          </label>
        </div>
      </div>
    </div>
  );
};
