import { useSelector } from 'react-redux';
import style from './style.module.css';
import React, { useEffect, useRef, useState } from 'react';
import { RootState, store } from '../../../../store/store';
import {
  Dialog,
  Message,
  selectMessage,
} from '../../../../store/actions/dialog-actions';
import { DialogMessage } from '../dialog-message/dialog-message';
import { setReaded } from '../../../../core/services/set-readed';
import {
  ContextMenu,
  ContextMenuItem,
  ContextMenuProps,
} from '../../../shared/context-menu/context-menu';
import { DialogActions } from '../../../../store/constants/action-constants';
import { sendMessage } from '../../../../core/services/send-message';

const getDialog = (login: string | null, dialogs: Dialog[]): Message[] => {
  const result: Message[] = [];
  dialogs.forEach((dialog) => {
    if (dialog.login === login) {
      result.push(...dialog.messages);
    }
  });
  return result;
};

const setScrollNewRef = (
  ref: React.RefObject<HTMLDivElement>,
  selectedUser: string | null,
  message: Message,
  index: number
): React.RefObject<HTMLDivElement> | undefined => {
  if (index === 0 && message.from === selectedUser) {
    return ref;
  }
  if (message.from !== selectedUser) {
    return ref;
  }
  return undefined;
};

export const DialogContent: React.FC = () => {
  const emptyHistoryText = 'Напишите ваше первое сообщение...';
  const newHistoryText = 'Новые сообщения';
  const selectUserText = 'Выберите пользователя для отправки сообщения...';

  const selectedUser = useSelector(
    (state: RootState) => state.users.userSelected.login
  );
  const [showedUser, setShowedUser] = useState('');

  const dialogs = useSelector((store: RootState) => store.dialogs.messages);

  const [oldDialogHistory, setOldDialogHistory] = useState(
    new Array<Message>()
  );
  const [newDialogHistory, setNewDialogHistory] = useState(
    new Array<Message>()
  );
  const [isShowDelimier, setShowDelimier] = useState(false);

  useEffect(() => {
    const currentDialog = getDialog(selectedUser, dialogs);
    const oldMessages = currentDialog.filter(
      (message) => message.status.isReaded !== false
    );
    const newMessages = currentDialog.filter(
      (message) => message.status.isReaded === false
    );

    setOldDialogHistory(oldMessages);
    setNewDialogHistory(newMessages);

    if (newMessages.length > 0 && newMessages[0].from === selectedUser) {
      setShowDelimier(true);
    } else {
      setShowDelimier(false);
    }

    setShowedUser(selectedUser || '');
  }, [dialogs, selectedUser]);

  useEffect(() => {
    if (selectedUser === showedUser && !isShowDelimier) {
      setReaded();
    }
  }, [dialogs]);

  const readMessagesHandler = () => {
    setShowDelimier(false);
    setReaded();
  }

  const scrollNewRef = useRef<HTMLDivElement>(null);
  const scrollOldRef = useRef<HTMLDivElement>(null);
  const delimierRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (isShowDelimier) {
      delimierRef.current?.scrollIntoView({ behavior: 'smooth' });
    } else if (newDialogHistory.length > 0) {
      scrollNewRef.current?.scrollIntoView({ behavior: 'smooth' });
    } else {
      scrollOldRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [
    isShowDelimier,
    delimierRef,
    scrollNewRef,
    scrollOldRef,
    newDialogHistory,
    oldDialogHistory,
  ]);

  const [contextMenu, setContextMenu] = useState<ContextMenuProps | null>(null);
  const menuSelectHandler = (
    id: string,
    action: DialogActions.MSG_DELETE | DialogActions.SELECT_MESSAGE
  ) => {
    if (action === DialogActions.MSG_DELETE) {
      const payload = {
        message: {
          id: id,
        },
      };
      sendMessage(DialogActions.MSG_DELETE, payload);
    }
    if (action === DialogActions.SELECT_MESSAGE) {
      store.dispatch(selectMessage(id));
    }
    setContextMenu(null);
  };
  const contextMenuItems: ContextMenuItem[] = [
    {
      name: 'Изменить',
      callback: (id) =>
        menuSelectHandler.bind(this, id, DialogActions.SELECT_MESSAGE)(),
    },
    {
      name: 'Удалить',
      callback: (id) =>
        menuSelectHandler.bind(this, id, DialogActions.MSG_DELETE)(),
    },
  ];
  const contextMenuHandler = (
    event: React.MouseEvent | React.TouchEvent,
    idMessage: string
  ) => {
    const contextMenu: ContextMenuProps = {
      event: event,
      id: idMessage,
      items: contextMenuItems,
    };
    event.currentTarget.scrollIntoView({ behavior: 'smooth', block: 'end' });
    setContextMenu(contextMenu);
  };
  useEffect(() => {
    document.addEventListener('click', () => setContextMenu(null));
  });

  return (
    <article
      className={style['dialog-content']}
      onClick={readMessagesHandler}
      onWheel={readMessagesHandler}
      ref={delimierRef}
    >
      <div className={style.spacer}></div>
      {selectedUser === null && (
        <label className={style.info}>{selectUserText}</label>
      )}
      {selectedUser !== null &&
        oldDialogHistory.length === 0 &&
        newDialogHistory.length === 0 && (
          <label className={style.info}>{emptyHistoryText}</label>
        )}
      {oldDialogHistory.map((message) => (
        <DialogMessage
          message={message}
          key={message.id}
          innerRef={scrollOldRef}
          menuCallback={contextMenuHandler}
        />
      ))}
      {isShowDelimier && (
        <div className={style['history-delimier']} ref={delimierRef}>
          <label className={style['delimier-text']}>{newHistoryText}</label>
        </div>
      )}
      {newDialogHistory.map((message, index) => (
        <DialogMessage
          message={message}
          key={message.id}
          innerRef={setScrollNewRef(scrollNewRef, selectedUser, message, index)}
          menuCallback={contextMenuHandler}
        />
      ))}
      {contextMenu !== null && <ContextMenu {...contextMenu} />}
    </article>
  );
};
