import { useSelector } from 'react-redux';
import style from './style.module.css';
import React, { useEffect, useState } from 'react';
import { RootState } from '../../../../store/store';

export const DialogHeader: React.FC = () => {
  const textActive = 'в сети';
  const textInActive = 'не в сети';

  const activeUser = useSelector(
    (store: RootState) => store.users.usersAnother.active
  );

  const selectedUser = useSelector(
    (store: RootState) => store.users.userSelected.login
  );
  const [active, setActive] = useState(false);

  useEffect(() => {
    if (activeUser) {
      const isActive = activeUser.some((user) => user.login === selectedUser);
      setActive(isActive);
    }
  }, [activeUser, selectedUser]);

  return (
    <article className={style['dialog-header']}>
      <label>{selectedUser}</label>
      {selectedUser && (
        <label
          className={active ? style['user-active'] : style['user-inactive']}
        >
          {active ? textActive : textInActive}
        </label>
      )}
    </article>
  );
};
